// import React, { useEffect, useState } from 'react';
import { useSelector, useDispatch } from "react-redux";
import { logout, setUser } from "@/lib/auth";
import {
  ChartNoAxesCombined,
  ChevronRight,
  Globe,
  Menu,
  ReceiptText,
  X,
} from "lucide-react";
import Logo from "../components/logo";
